private static SqlCallBinding mockCallBinding(SqlFunction function, List<OperandSpec> actualOperands) {
    SqlValidator validator = Mockito.mock(SqlValidator.class);
    Mockito.when(validator.getTypeFactory()).thenReturn(new SqlTypeFactoryImpl(DruidTypeSystem.INSTANCE));
    List<SqlNode> operands = new ArrayList<>(actualOperands.size());
    for (OperandSpec operand : actualOperands) {
        final SqlNode node;
        if (operand.isLiteral) {
            node = Mockito.mock(SqlLiteral.class);
        } else {
            node = Mockito.mock(SqlNode.class);
        }
        RelDataType relDataType = Mockito.mock(RelDataType.class);
        if (operand.isNullable) {
            Mockito.when(relDataType.isNullable()).thenReturn(true);
        } else {
            Mockito.when(relDataType.isNullable()).thenReturn(false);
        }
        Mockito.when(validator.deriveType(ArgumentMatchers.any(), ArgumentMatchers.eq(node))).thenReturn(relDataType);
        Mockito.when(relDataType.getSqlTypeName()).thenReturn(operand.type);
        operands.add(node);
    }
    SqlParserPos pos = Mockito.mock(SqlParserPos.class);
    Mockito.when(pos.plusAll(ArgumentMatchers.any(Collection.class))).thenReturn(pos);
    SqlCallBinding callBinding = new SqlCallBinding(validator, Mockito.mock(SqlValidatorScope.class), function.createCall(pos, operands));
    Mockito.when(validator.newValidationError(ArgumentMatchers.any(), ArgumentMatchers.any())).thenAnswer((Answer<CalciteContextException>) invocationOnMock -> new CalciteContextException(StringUtils.format("Exception in test for operator[%s]", function.getName()), invocationOnMock.getArgument(1, ExInst.class).ex()));
    return callBinding;
}

